import React, { useEffect, useState } from "react";
import Home from "./Sections/Home";
import "./App.css";
import About from "./Sections/About";
import Testimonial from "./Sections/Testimonial";
import GalleryAndAwards from "./Sections/GalleryAndAwards";
import Footer from "./Sections/Footer";

// Replace with your Google Apps Script Web App URL
const GOOGLE_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzWZkvYYwsl-2PEkDd6vNnkdzSJ5tEDB2DhLyRLyVYyA-gon7VN4GxEkqdBdpY0QR2U2A/exec";

const SecurityProtection = () => {
  useEffect(() => {
    const handleContextMenu = (e) => e.preventDefault();

    const handleKeyUp = async (e) => {
      if (e.key === "PrintScreen" || e.keyCode === 44) {
        try {
          await navigator.clipboard.writeText("");
        } catch {}
        alert("Screenshots are discouraged.");
      }
      if (e.ctrlKey && e.key.toLowerCase() === "p") {
        alert("Printing is disabled.");
        e.preventDefault();
        e.stopImmediatePropagation();
      }
    };

    const handleKeyDown = (e) => {
      if (
        e.keyCode === 123 ||
        (e.ctrlKey && e.shiftKey && [73, 74, 67].includes(e.keyCode)) ||
        (e.ctrlKey && e.keyCode === 85)
      ) {
        e.preventDefault();
        return false;
      }
      if (e.metaKey && e.shiftKey && (
        e.key === "4" || e.key === "5" || e.keyCode === 52 || e.keyCode === 53
      )) {
        e.preventDefault();
        e.stopImmediatePropagation();
        return false;
      }
    };

    const checkDevTools = () => {
      const w = window.outerWidth - window.innerWidth > 160;
      const h = window.outerHeight - window.innerHeight > 160;
      if (w || h) {
        document.body.innerHTML = `
        <div style="display:flex;justify-content:center;align-items:center;height:100vh;font-family:Arial;">
          <h2>Developer tools are not allowed</h2>
        </div>`;
      }
    };

    const style = document.createElement("style");
    style.innerHTML = `
      .protected-element {
        -webkit-user-select: none;
        -moz-user-select: none;
        -ms-user-select: none;
        user-select: none;
        -webkit-touch-callout: none;
      }
      * {
        -webkit-touch-callout: none;
        -webkit-user-select: none;
        -khtml-user-select: none;
        -moz-user-select: none;
        -ms-user-select: none;
        user-select: none;
      }
      input, textarea {
        -webkit-user-select: text;
        -moz-user-select: text;
        -ms-user-select: text;
        user-select: text;
      }
      img {
        -webkit-user-drag: none;
        -khtml-user-drag: none;
        -moz-user-drag: none;
        -o-user-drag: none;
        user-drag: none;
      }
    `;
    document.head.appendChild(style);

    const handleBlur = () => { document.body.style.filter = "blur(5px)"; };
    const handleFocus = () => { document.body.style.filter = "none"; };
    const handleDragStart = (e) => e.preventDefault();
    const preventMobileZoom = (e) => e.preventDefault();

    document.addEventListener("contextmenu", handleContextMenu);
    document.addEventListener("keyup", handleKeyUp, true);
    document.addEventListener("keydown", handleKeyDown, true);
    window.addEventListener("blur", handleBlur);
    window.addEventListener("focus", handleFocus);
    document.body.addEventListener("dragstart", handleDragStart);

    document.addEventListener("gesturestart", preventMobileZoom);
    document.addEventListener("gesturechange", preventMobileZoom);
    document.addEventListener("gestureend", preventMobileZoom);

    const devToolsInterval = setInterval(checkDevTools, 2000);

    return () => {
      document.removeEventListener("contextmenu", handleContextMenu);
      document.removeEventListener("keyup", handleKeyUp, true);
      document.removeEventListener("keydown", handleKeyDown, true);
      window.removeEventListener("blur", handleBlur);
      window.removeEventListener("focus", handleFocus);
      document.body.removeEventListener("dragstart", handleDragStart);
      document.removeEventListener("gesturestart", preventMobileZoom);
      document.removeEventListener("gesturechange", preventMobileZoom);
      document.removeEventListener("gestureend", preventMobileZoom);
      clearInterval(devToolsInterval);
      document.head.removeChild(style);
    };
  }, []);

  return null;
};

const withProtection = (WrappedComponent) => {
  return (props) => (
    <>
      <SecurityProtection />
      <WrappedComponent {...props} />
    </>
  );
};

const App = () => {
  const [contentData, setContentData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    document.body.classList.add("protected-element");
  }, []);

  // Fetch data from Google Apps Script
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        setError(null);

        // Add timestamp to avoid caching and use the correct endpoint
        const url = `${GOOGLE_SCRIPT_URL}?action=getData&t=${Date.now()}`;

        const response = await fetch(url);

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const result = await response.json();

        if (result.success && result.data) {
          setContentData(result.data);
        } else {
          throw new Error(result.message || "No data found in Google Sheets");
        }
      } catch (err) {
        console.error("Error fetching data:", err);
        setError(err.message);
        // Don't set any default data
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return (
      <div className="flex justify-center items-center h-screen bg-white">
        <div className="text-center">
          {/* Orange Material-UI inspired loader */}
          <div className="relative inline-block">
            <div className="w-16 h-16 border-4 border-orange-200 rounded-full"></div>
            <div className="absolute top-0 left-0 w-16 h-16 border-4 border-orange-500 rounded-full animate-spin border-t-transparent"></div>
          </div>
          {/* <p className="mt-6 text-orange-600 font-medium text-lg">Loading content...</p>
          <p className="mt-2 text-gray-500 text-sm">Fetching latest data from our servers</p> */}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex justify-center items-center h-screen bg-white">
        <div className="text-center max-w-md mx-4">
          <div className="text-red-500 text-6xl mb-4">⚠️</div>
          <h2 className="text-xl font-bold text-gray-800 mb-2">Content Not Available</h2>
          <p className="text-gray-600 mb-6">We're having trouble loading the content at the moment.</p>
          <button 
            onClick={() => window.location.reload()}
            className="px-6 py-3 bg-orange-500 text-white rounded-lg hover:bg-orange-600 transition-colors font-medium"
          >
            Try Again
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="App px-2 protected-element">
      <SecurityProtection />

      {contentData && (
        <>
          <Home 
            mainHeading={contentData.MainHeading}
            mainDescription={contentData.MainDescription}
            mainBG={contentData.mainBG}
            mainBGmb={contentData.mainBGmb}
          />
          <About 
            aboutHeading={contentData.AboutHeading}
            aboutDescription={contentData.AboutDescription}
            feature1Heading={contentData.dh1}
            feature1Description={contentData.dd1}
            feature2Heading={contentData.dh2}
            feature2Description={contentData.dd2}
            images={[contentData.img1, contentData.img2, contentData.img3]}
            coachingHeading={contentData.coaching}
            coachingDescription={contentData.coachingDes}
            groupCoachingHeading={contentData.Groupcoaching}
            groupCoachingDescription={contentData.GroupcoachingDes}
            price={contentData.oneTimeCharge}
            timing1Heading={contentData.Timingh1}
            timing1Description={contentData.Timingd1}
            timing2Heading={contentData.Timingh2}
            timing2Description={contentData.Timingd2}
          />
          <Testimonial />
          <GalleryAndAwards />
          <Footer />
        </>
      )}
    </div>
  );
};

export default withProtection(App);
